/**
 * The curated colour themes (docs/notes/theme-slots-1-engine.md). catalog.json is
 * generated by themes/convert.ts (`pnpm run themes`) and committed: each entry is a theme
 * file (base + overrides). Its slots are resolved here on first use by the rules in
 * ./slots.ts, and lib/theme.ts applies the active theme's slots to <html> as CSS variables.
 */
import catalog from "./catalog.json";
import { componentValues, resolveSlots, type ThemeFile, type ThemeScheme } from "./slots";

export type { ThemeBase, ThemeFile, ThemeScheme } from "./slots";

export interface Theme extends ThemeFile {
  /**
   * Every slot's value: `--cf-*`, `--terminal-*`, `--syn-*` and `--sh-*`, `#rrggbb` or
   * (tints) `#rrggbbaa`. What lib/theme.ts sets on <html> and a ThemeScope on its element.
   */
  readonly slots: Readonly<Record<string, string>>;
  /** The slots plus the component names (`--pane`, `--primary`, ...) as index.css's aliases resolve them. */
  readonly vars: Readonly<Record<string, string>>;
}

/** A theme file with its slots resolved once, on first read. */
export function themeOf(file: ThemeFile): Theme {
  let slots: Record<string, string> | undefined;
  let vars: Record<string, string> | undefined;
  return Object.freeze({
    ...file,
    get slots() {
      return (slots ??= resolveSlots(file));
    },
    get vars() {
      const s = (slots ??= resolveSlots(file));
      return (vars ??= { ...s, ...componentValues(s) });
    },
  });
}

export const themes: readonly Theme[] = (catalog as ThemeFile[]).map(themeOf);

export const themeById: ReadonlyMap<string, Theme> = new Map(themes.map((t) => [t.id, t]));

export { DEFAULT_DARK, DEFAULT_LIGHT } from "./defaults";

/** The themes that can fill a scheme's slot, in catalog order (the default first). */
export function themesFor(scheme: ThemeScheme): readonly Theme[] {
  return themes.filter((t) => t.scheme === scheme);
}
